    [63796] = {
        category = "Dungeon and Raids",
        source = "Yogg-Saron with no Keepers assisting - Ulduar",
        npcId = 33288,
        tips = "Current Ulduar has one merged size. The mount condition is zero assisting Keepers, not a 25-player selector. Do not talk to the defeated Keepers to request their help.",
        sourceComments = { 806970, 2019134 },
        waypoints = {
            {
                mapID = 120,
                x = 0.41600000000000004,
                y = 0.182,
                step = 1,
                label = "Ulduar raid entrance - zero-Keeper Yogg route",
                mapName = "The Storm Peaks",
            },
        },
        itemId = 45693,
        name = "Mimiron's Head",
        mountCategory = "Dungeon and Raids",
        stepCount = 7,
        acquisition = "Difficulty: Hard - A rare drop with daily or weekly loot limits can require many repeated clears.\n\n1. Enter the normal legacy Ulduar raid in the Storm Peaks (41.6, 18.2), rather than a queued Timewalking instance. Use your own weekly lockout. The old instructions to clear in 10-player and switch to 25-player are obsolete after Ulduar's merger.\n\n2. Start the entrance assault, use a siege vehicle if needed, and defeat Flame Leviathan. Continue through XT-002 Deconstructor and Kologarn into the inner ring. Ignis, Razorscale, and the Assembly of Iron are not required detours just to reach Yogg-Saron.\n\n3. Defeat Hodir, Thorim, Freya, and Mimiron to unlock the way onward. After each win, leave that Keeper's assistance dialogue alone. Their defeated friendly versions on the inner ring must not be asked to help in Yogg-Saron's chamber.\n\n4. Defeat General Vezax and enter Yogg-Saron's prison. Keep zero Keepers assisting. In the first phase, kill the spawned Guardians beside Sara so their explosions trigger the phase transition; repeatedly hitting Sara directly does not replace this mechanic.\n\n5. When the portal phase begins, enter a brain portal, clear the illusion's tentacles, and damage the brain before Induce Madness completes. Use the exit portal in time and avoid losing all Sanity; repeat the portal sequence if needed.\n\n6. In the final phase, turn away from Lunatic Gaze when necessary, kill Yogg-Saron, and loot him. Learn Mimiron's Head if it drops. Alone in the Darkness can confirm the zero-Keeper setup, but completing it does not guarantee the mount.\n\n7. Return after the weekly reset or use another eligible character if the mount did not drop. Re-running the same saved boss or changing a legacy size setting does not produce another roll.",
        wowheadUrl = "https://www.wowhead.com/item=45693",
        difficultyReason = "A rare drop with daily or weekly loot limits can require many repeated clears.",
        difficulty = "hard",
    },
