    [64731] = {
        category = "Fishing",
        source = "Rare catch from eligible fishing pools",
        tips = "The map pins are starting areas for pool fishing, not fixed turtle spawns. Cast into the visible school of fish. No exact number of catches guarantees the mount.",
        sourceComments = { 1900057, 1607166, 682545, 929176 },
        waypoints = {
            {
                mapID = 119,
                x = 0.38,
                y = 0.39,
                step = 2,
                label = "Bittertide Lake - Nettlefish pool circuit starting area",
                mapName = "Sholazar Basin",
            },
            {
                mapID = 117,
                x = 0.48,
                y = 0.39,
                step = 3,
                label = "Howling Fjord lakes - alternate fishing-pool search area",
                mapName = "Howling Fjord",
            },
        },
        itemId = 46109,
        name = "Sea Turtle",
        mountCategory = "Other",
        stepCount = 5,
        acquisition = "Difficulty: Hard - Fish eligible pools repeatedly for a very rare catch; there is no guaranteed completion count.\n\n1. Learn Fishing, make room in your bags, and choose a region with many accessible pools. If you know Find Fish, enable its minimap tracking. Higher Fishing skill does not create a special guaranteed turtle roll.\n\n2. For a simple Northrend route, start at Bittertide Lake in northwestern Sholazar Basin (about 38.0, 39.0). Move around the shoreline and fish each visible Nettlefish school until it disappears. Cast so the bobber lands inside the pool, not just somewhere in the lake.\n\n3. If the lake is crowded or empty, use a different pool circuit. Fangtooth Herring schools in Howling Fjord's lakes, including the area near 48.0, 39.0, are another option and can also yield the Dark Herring achievement fish. Switch the map dropdown to compare the two starting areas.\n\n4. Continue from pool to pool, loot every catch, and keep bag space available. This is a rare catch with no daily dungeon-style lockout; unsuccessful casts do not make a specific later cast guaranteed.\n\n5. When Sea Turtle appears in the loot, take the item before moving or cancelling the window, then use it to learn the mount. Eligible Cataclysm, Pandaria, and Draenor pools offer alternate fishing routes if you prefer their fish; Northrend is not the only surviving Retail source.",
        wowheadUrl = "https://www.wowhead.com/item=46109",
        difficultyReason = "Fish eligible pools repeatedly for a very rare catch; there is no guaranteed completion count.",
        difficulty = "hard",
    },
    [64977] = {
        category = "Vendor",
        source = "Zachariah Post - Brill",
        npcId = 4731,
        cost = "1 gold base, reduced by reputation discounts",
        tips = "Horde only. The matching original race skips the reputation grind. Allied races are separate races; use the vendor's eligibility requirement. Ordinary mounts scale with your riding skill.",
        waypoints = {
            {
                mapID = 18,
                x = 0.6940000000000001,
                y = 0.628,
                step = 2,
                label = "Zidormi - restore pre-battle Tirisfal",
                mapName = "Tirisfal Glades",
            },
            {
                mapID = 90,
                x = 0.636,
                y = 0.488,
                step = 2,
                label = "Captain Donald Adams - optional Undercity Tabard",
                mapName = "Undercity",
            },
            {
                mapID = 109,
                x = 0.715,
                y = 0.555,
                step = 3,
                label = "The Botanica - optional tabard reputation runs",
                mapName = "Netherstorm",
            },
            {
                mapID = 18,
                x = 0.618,
                y = 0.518,
                step = 4,
                label = "Zachariah Post - Black Skeletal Horse",
                mapName = "Tirisfal Glades",
            },
        },
        itemId = 46308,
        name = "Black Skeletal Horse",
        mountCategory = "Vendor",
        stepCount = 5,
        acquisition = "Difficulty: Easy - Use the matching original race to buy this inexpensive racial mount directly.\n\n1. Use a Horde character with riding unlocked. An original Undead can buy this racial mount without Exalted; other races need Exalted with Undercity. If already eligible, go directly to the vendor step.\n\n2. If reputation is needed, equip the Undercity Tabard from its city quartermaster. Use the quartermaster beside the city flight master; for Undercity, restore the pre-battle Tirisfal phase with Zidormi first, then visit Captain Donald Adams underground.\n\n3. With the tabard equipped, clear Normal Botanica in Netherstorm (71.5, 55.5) on a character able to solo it. Confirm the correct city reputation increases, take the exit behind Warp Splinter, reset outside, and repeat to Exalted. Pause at the hourly instance limit.\n\n4. Visit Zachariah Post at Brill (61.8, 51.8). If Brill is destroyed in your phase, speak to Zidormi in Tirisfal Glades (69.4, 62.8) to restore the pre-battle zone first. Buy Black Skeletal Horse for up to 1 gold.\n\n5. Use the mount item and search Collections > Mounts for Black Skeletal Horse. This is a normal racial purchase, not a PvP currency mount or an Argent Tournament reward.",
        wowheadUrl = "https://www.wowhead.com/item=46308",
        difficultyReason = "Use the matching original race to buy this inexpensive racial mount directly.",
        difficulty = "easy",
    },
    [65637] = {
        category = "Argent Tournament",
        source = "Irisee - Champion of the Exodar",
        npcId = 33657,
        difficulty = "medium",
        difficultyReason = "Daily-gated city training, followed by a small seal-and-gold purchase.",
        cost = "5 Champion's Seals and 500 gold before applicable reputation discounts",
        requirements = "Eligible faction and access to this city's Argent Tournament quartermaster.",
        tips = "This is a separate appearance from the 100-seal city mount. Check the seller's current requirements and displayed price. If another city's reputation is required, its physical city tabard and the original city guide give the current reputation route.",
        sources = { "https://www.wowhead.com/item=46745", "https://www.wowhead.com/spell=65637" },
        waypoints = {
            {
                mapID = 118,
                x = 0.696,
                y = 0.228,
                step = 1,
                label = "Justicar Mariel Trueheart - Tournament introduction",
                mapName = "Icecrown",
            },
            {
                mapID = 118,
                x = 0.7509999999999999,
                y = 0.218,
                step = 5,
                label = "Trial of the Champion - optional original Heroic seals",
                mapName = "Icecrown",
            },
            {
                mapID = 118,
                x = 0.762,
                y = 0.192,
                step = 6,
                label = "Irisee - Champion of the Exodar - Great Red Elekk",
                mapName = "Icecrown",
            },
        },
        itemId = 46745,
        name = "Great Red Elekk",
        mountCategory = "Vendor",
        stepCount = 7,
        acquisition = "1. Begin The Argent Tournament with Justicar Mariel Trueheart in Icecrown at 69.6, 22.8. Follow your faction introduction and complete the three mounted-combat lessons.\n\n2. Accept Up To The Challenge, complete the offered Aspirant dailies across resets for fifteen Aspirant's Seals, then win The Aspirant's Challenge with the supplied lance and tournament steed.\n\n3. Train the first city offered to your race. Earn twenty-five Valiant's Seals from its dailies, complete The Valiant's Charge and win The Valiant's Challenge. Turn in A Champion Rises to open Champion activities.\n\n4. If the desired city differs from your first championship, take that city's Valiant invitation and complete its own twenty-five-seal training and challenge. Only one city's new training can be active at a time. The live quest section advances to this character's unfinished stage.\n\n5. Earn five CHAMPION'S Seals from unlocked Champion dailies or the original Heroic Trial of the Champion. Aspirant's and Valiant's Seals are different items and cannot pay this price.\n\n6. Visit Irisee - Champion of the Exodar. Buy Great Red Elekk for five Champion's Seals plus the displayed gold price, up to the 500-gold base. Check the original city's vendor pin below; the 100-seal mount beside it is a different appearance.\n\n7. Use the purchased reins to learn the mount. Check the Mount Journal and eligible faction counterpart before repeating a complete training route on another character.",
        wowheadUrl = "https://www.wowhead.com/item=46745",
    },
